class Solution {
    public List<String> findHighAccessEmployees(List<List<String>> access_times){
        Map<String,List<Integer>> times=new TreeMap<>();
        for(List<String> access:access_times){
            String value=access.get(1);
            int minute=Integer.parseInt(value.substring(0,2))*60+Integer.parseInt(value.substring(2));
            times.computeIfAbsent(access.get(0),ignored->new ArrayList<>()).add(minute);
        }
        List<String> answer=new ArrayList<>();
        for(Map.Entry<String,List<Integer>> entry:times.entrySet()){
            List<Integer> values=entry.getValue();
            Collections.sort(values);
            for(int i=2;i<values.size();i++)if(values.get(i)-values.get(i-2)<60){
                answer.add(entry.getKey());
                break;
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findHighAccessEmployees(access_times:List<List<String>>):List<String>{
        val times=java.util.TreeMap<String,MutableList<Int>>();
        for(access in access_times){
            val value=access[1];
            val minute=value.substring(0,2).toInt()*60+value.substring(2).toInt();
            times.getOrPut(access[0]){
                mutableListOf()
            }.add(minute)
        };
        val answer=mutableListOf<String>();
        for((name,values) in times){
            values.sort();
            for(i in 2 until values.size)if(values[i]-values[i-2]<60){
                answer.add(name);
                break
            }
        };
        return answer
    }
}

